import{_ as a,o as n,c as e,ag as i}from"./chunks/framework.CmaAMB6e.js";const g=JSON.parse('{"title":"03 · API 与数据流设计","description":"","frontmatter":{"概念":"API 与数据流设计","技能":"system-design","阶段":"1-方法论","状态":"⬜未开始","更新日期":"2026-08-01T00:00:00.000Z","前置":"02 容量估算","耗时":"1.5~2 小时"},"headers":[],"relativePath":"system-design/concepts/03-api-dataflow.md","filePath":"system-design/concepts/03-api-dataflow.md","lastUpdated":null}'),t={name:"system-design/concepts/03-api-dataflow.md"};function p(l,s,r,o,c,d){return n(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="_03-·-api-与数据流设计" tabindex="-1">03 · API 与数据流设计 <a class="header-anchor" href="#_03-·-api-与数据流设计" aria-label="Permalink to &quot;03 · API 与数据流设计&quot;">​</a></h1><blockquote><p><strong>前置</strong>：02 容量估算 · <strong>预计</strong>：1.5~2 小时</p></blockquote><h2 id="概念简介" tabindex="-1">概念简介 <a class="header-anchor" href="#概念简介" aria-label="Permalink to &quot;概念简介&quot;">​</a></h2><p>API 是系统对外的<strong>公共契约</strong>：一旦发布，调用方（前端、其他服务、第三方）就依赖它，改接口等于改契约。系统设计阶段的 API 设计关心的不是怎么实现路由，而是<strong>资源怎么命名、语义怎么表达、分页与错误怎么约定</strong>——这些决定了下游能否稳定对接，也决定了未来能不能平滑演进。</p><p>数据流设计则是画清楚「一次请求经过哪些组件、数据在哪里转换、哪里是瓶颈」。前端看重的 React 数据流（props 单向流动）在后端同样成立：<strong>画数据流图先于写代码</strong>，它能让模块边界、缓存位置、异步切分点在设计阶段就暴露出来。</p><p>本概念把三件事串起来：API 契约（系统怎么说话）、数据流图（数据怎么走）、状态机（数据怎么变）。三者合起来就是系统的「行为规范」。</p><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><h4 id="_1-api-设计原则-rest-资源语义" tabindex="-1">1. API 设计原则：REST 资源语义 <a class="header-anchor" href="#_1-api-设计原则-rest-资源语义" aria-label="Permalink to &quot;1. API 设计原则：REST 资源语义&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>资源是名词，操作是 HTTP 方法；URI 只放资源，不放动词</span></span>
<span class="line"><span></span></span>
<span class="line"><span>正确示范：</span></span>
<span class="line"><span>  GET    /api/v1/users?page=2&amp;page_size=20   列出用户（分页）</span></span>
<span class="line"><span>  POST   /api/v1/users                        创建用户</span></span>
<span class="line"><span>  GET    /api/v1/users/{id}                   单个用户</span></span>
<span class="line"><span>  PUT    /api/v1/users/{id}                   整体更新（幂等）</span></span>
<span class="line"><span>  PATCH  /api/v1/users/{id}                   部分更新</span></span>
<span class="line"><span>  DELETE /api/v1/users/{id}                   删除</span></span>
<span class="line"><span></span></span>
<span class="line"><span>错误示范：</span></span>
<span class="line"><span>  GET /api/getUserList       ← 动词进 URI</span></span>
<span class="line"><span>  GET /api/users/listAll      ← 语义重复</span></span>
<span class="line"><span>  POST /api/users/getUser    ← 用 POST 表达查询</span></span></code></pre></div><p>分页约定要尽早定：<strong>offset 分页</strong>（<code>page</code> + <code>page_size</code>）实现简单但深翻页慢；<strong>cursor 分页</strong>（<code>next_cursor</code>）适合高并发信息流（深翻页 O(1)）。返回体里带上 <code>total</code> 通常是不必要的开销——列表页往往不知道总量。</p><p>错误契约用统一信封：状态码表达语义（400 参数错 / 401 未认证 / 403 无权限 / 404 不存在 / 429 限流 / 5xx 服务端），body 里给机器可读的 error code + 人类可读的 message。版本化放路径（<code>/api/v1</code>）最直观，放 Header 对 URL 短链类系统更友好——<strong>选了就坚持</strong>。</p><h4 id="_2-数据流图-data-flow-diagram" tabindex="-1">2. 数据流图（Data Flow Diagram） <a class="header-anchor" href="#_2-数据流图-data-flow-diagram" aria-label="Permalink to &quot;2. 数据流图（Data Flow Diagram）&quot;">​</a></h4><p>数据流图回答：<strong>谁产出数据、经过哪些组件、谁消费</strong>。以短链系统重定向为例：</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant 用户</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant DNS</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant LB as 负载均衡</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant 缓存 as Redis 缓存</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant DB as MySQL</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant 统计 as 统计服务(异步)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    用户-&gt;&gt;DNS: 访问 t.cn/abc123</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    DNS-&gt;&gt;LB: 解析到机房入口</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    LB-&gt;&gt;缓存: 查 code=abc123</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    alt 缓存命中</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        缓存--&gt;&gt;LB: 返回原 URL（2 ms）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    else 缓存未命中</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        LB-&gt;&gt;DB: 回源查询</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        DB--&gt;&gt;LB: 返回原 URL（10 ms）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    LB--&gt;&gt;用户: 302 Location: 原 URL</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    用户-&gt;&gt;统计: 上报点击事件（异步，不阻塞重定向）</span></span></code></pre></div><p>从图里能直接读出三个设计决策：读路径缓存化（热点短链）、写统计异步化（不让统计拖慢主路径）、回源只在未命中时发生。<strong>画图的收益是发现「数据要不要经过某个组件」</strong>——比如统计其实不需要经过 LB，它可以直接走消息队列。</p><h4 id="_3-状态机设计" tabindex="-1">3. 状态机设计 <a class="header-anchor" href="#_3-状态机设计" aria-label="Permalink to &quot;3. 状态机设计&quot;">​</a></h4><p>订单类、流程类数据的变更必须用状态机约束，否则会出现「已支付→已退款→再支付」这类非法迁移。先画状态图，再定迁移表：</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stateDiagram-v2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    [*] --&gt; 待支付</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    待支付 --&gt; 已支付: 支付成功</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    待支付 --&gt; 已取消: 超时/用户取消</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    已支付 --&gt; 已发货: 发货</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    已发货 --&gt; 已完成: 确认收货</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    已支付 --&gt; 已退款: 退款</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    已退款 --&gt; [*]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    已完成 --&gt; [*]</span></span></code></pre></div><p>状态机的实现要点：<strong>状态迁移是单写者</strong>（一个服务负责改状态，其他服务只能发事件/请求），迁移要记审计日志（谁在什么时候从什么状态改成什么）。前端对照：Redux 里的 reducer 天然是状态机——<code>switch(action.type)</code> 就是迁移函数，非法 action 会被 default 分支拒绝。</p><h4 id="_4-关键路径与瓶颈识别" tabindex="-1">4. 关键路径与瓶颈识别 <a class="header-anchor" href="#_4-关键路径与瓶颈识别" aria-label="Permalink to &quot;4. 关键路径与瓶颈识别&quot;">​</a></h4><p>把「用户能感知的请求」拆成延迟预算，逐段标出成本：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>打开短链的端到端延迟预算（目标 &lt; 100 ms）：</span></span>
<span class="line"><span>  DNS 解析              5 ms</span></span>
<span class="line"><span>  网络往返（边缘→机房）  15 ms</span></span>
<span class="line"><span>  负载均衡转发           2 ms</span></span>
<span class="line"><span>  缓存查询              ~2 ms</span></span>
<span class="line"><span>  业务逻辑 + 序列化      20 ms</span></span>
<span class="line"><span>  ------------合计 ≈ 44 ms，余量充足</span></span>
<span class="line"><span></span></span>
<span class="line"><span>但假如统计上报走同步调用，加入 50 ms 后的结果：</span></span>
<span class="line"><span>  主路径 = 44 + 50 = 94 ms → 仍在预算内，但一旦统计服务故障</span></span>
<span class="line"><span>  → 整个重定向不可用（级联故障）→ 瓶颈与单点被识别</span></span></code></pre></div><p>识别出瓶颈后有两类解法：<strong>并行化</strong>（统计与重定向并行）、<strong>异步化</strong>（统计进消息队列，见 06）。关键路径分析的产出是一张「延迟预算表」——每个组件分到多少毫秒，上线后用链路追踪校验。</p><h4 id="_5-与前端-api-层设计对照" tabindex="-1">5. 与前端 API 层设计对照 <a class="header-anchor" href="#_5-与前端-api-层设计对照" aria-label="Permalink to &quot;5. 与前端 API 层设计对照&quot;">​</a></h4><p>前端项目里的 <code>api/</code> 目录（axios 封装 + service 层 + 类型定义）其实已经在做「契约管理」。后端 API 设计是这份契约的<strong>生产端</strong>：前端定义 <code>UserService.getList()</code> 的签名，后端要保证 <code>/api/v1/users</code> 的资源语义与分页约定和它一致。契约变更 = 前后端联调成本，所以后端 API 设计要稳，前端要容忍向后兼容（前端一般加不了字段，只能过滤）。</p><h4 id="_6-接口版本化与兼容策略" tabindex="-1">6. 接口版本化与兼容策略 <a class="header-anchor" href="#_6-接口版本化与兼容策略" aria-label="Permalink to &quot;6. 接口版本化与兼容策略&quot;">​</a></h4><p>契约会变，变的方式决定下游的痛苦程度：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>版本化三选一：</span></span>
<span class="line"><span>  ① 路径版本：/api/v1/users → /api/v2/users     最直观，成本最低 → 默认选它</span></span>
<span class="line"><span>  ② Header 版本：Accept: application/vnd.x.v2+json</span></span>
<span class="line"><span>     适合「URL 是资源标识、不能动」的场景（如 CDN 缓存键敏感）</span></span>
<span class="line"><span>  ③ 无版本：原地修改 → 只适合「内部服务 + 有灰度开关」的团队</span></span>
<span class="line"><span></span></span>
<span class="line"><span>向后兼容四原则（v1 下线前必须做到）：</span></span>
<span class="line"><span>  ① 只加字段，不删字段、不改字段语义（前端没升级也能跑）</span></span>
<span class="line"><span>  ② 新增可选字段，默认值要合理（旧的客户端拿不到就给默认）</span></span>
<span class="line"><span>  ③ 不改变错误码语义（前端 error handler 依赖它）</span></span>
<span class="line"><span>  ④ 旧版本保留期写进契约（如 v1 保留 6 个月后下线，提前 3 个月公告）</span></span></code></pre></div><p>版本化与前面的「资源命名」是一体的：<strong>命名决定 URL 的稳定性，版本决定 URL 的变更方式</strong>。前端 SDK 的习惯是「破坏性变更必须发大版本」，后端 API 同理——小版本加字段、大版本动语义。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><ul><li><strong>URI 里出现动词和动作</strong>：<code>/api/deleteUser</code> 迟早会乱，REST 语义是团队共同语言。</li><li><strong>分页格式各接口不统一</strong>：有的 <code>page</code>、有的 <code>offset</code>、有的 <code>cursor</code>，下游适配代码爆炸；契约文档要写明统一约定。</li><li><strong>状态直接裸改数据库</strong>：绕过状态机 <code>UPDATE orders SET status=&#39;已完成&#39;</code> 跳过「已发货」，退款后还能发货；必须走单一状态迁移入口。</li><li><strong>统计/埋点进主链路</strong>：附属功能同步阻塞主路径，统计服务一挂整个系统不可用；异步化 + 降级是标配。</li><li><strong>错误响应格式不统一</strong>：一个接口 <code>{message}</code>、一个接口 <code>{error: {msg}}</code>，前端 error handler 写死只在某个格式上工作。</li><li><strong>改了接口不更新文档</strong>：契约过期比没有契约更危险，OpenAPI 生成 + CI 校验是底线。</li></ul><h2 id="练习建议" tabindex="-1">练习建议 <a class="header-anchor" href="#练习建议" aria-label="Permalink to &quot;练习建议&quot;">​</a></h2><ol><li><strong>基础</strong>：给你做过的任意 CRUD 后端设计一份 REST 契约（资源命名、方法、分页、错误格式），画出对应数据流图。</li><li><strong>进阶</strong>：为「下单 → 支付 → 发货 → 完成/退款」画完整状态机图，并设计状态迁移表（当前状态 × 动作 × 目标状态 × 谁允许触发）。</li><li><strong>综合</strong>：分析一个真实系统（如点餐 App）的关键路径：画出端到端时序图，标出每一步延迟预算，找出可以异步化或并行化的点，输出改造方案。</li></ol><blockquote><p>用 <code>/practice system-design API 与数据流设计</code> 生成更多针对性练习。</p></blockquote><h2 id="前端对照" tabindex="-1">前端对照 <a class="header-anchor" href="#前端对照" aria-label="Permalink to &quot;前端对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>前端架构概念</th><th>系统设计对应</th></tr></thead><tbody><tr><td>axios 封装 + service 层管理接口</td><td>API 契约设计（资源语义/分页/错误）</td></tr><tr><td>Redux reducer = 状态机</td><td>后端订单状态机 + 迁移表</td></tr><tr><td>React 单向数据流</td><td>数据流图（组件 = 服务，props = 数据流）</td></tr><tr><td>API 层接口类型定义（TS interface）</td><td>OpenAPI Schema（契约双方共用）</td></tr><tr><td>首屏性能优化（关键路径分析）</td><td>延迟预算 + 关键路径瓶颈识别</td></tr><tr><td>页面骨架屏/降级 UI</td><td>附属服务失败时的降级（统计挂了不阻塞主流程）</td></tr></tbody></table><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to &quot;参考链接&quot;">​</a></h2><ul><li><a href="https://learn.microsoft.com/en-us/azure/architecture/best-practices/api-design" target="_blank" rel="noreferrer">Microsoft REST API 设计指南</a></li><li><a href="https://swagger.io/specification/" target="_blank" rel="noreferrer">OpenAPI 规范</a></li><li><a href="https://martinfowler.com/articles/state-machine.html" target="_blank" rel="noreferrer">State Machine 设计模式（Martin Fowler）</a></li></ul>`,38)])])}const E=a(t,[["render",p]]);export{g as __pageData,E as default};
